// Check Duplicate — Google Sheets
const rows = $input.all();
const prepareNode = $('Prepare Data').first().json;
const now = new Date(prepareNode.received_at).getTime();

const dupKey = prepareNode.reporter + '_' +
  (prepareNode.raw_message || '')
    .normalize('NFC')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .substring(0, 80);

let isDuplicate = false;
for (const row of rows) {
  if (row.json.cache_key === dupKey) {
    const createdAt = new Date(row.json.created_at).getTime();
    const diffMin = (now - createdAt) / 1000 / 60;
    if (diffMin <= 10) {
      isDuplicate = true;
      break;
    }
  }
}

return [{
  json: {
    ...prepareNode,
    is_duplicate: isDuplicate,
    duplicate_key: dupKey
  }
}];

// ============================================
// Build IT Group Notify Message v6
// ============================================

const jiraNode    = $('Create an issue').first().json;
const defaultNode = $('Set default filed').first().json;
const prepareNode = $('Prepare Data').first().json;

// ดึงชื่อจาก LINE API
let displayName = 'ไม่ระบุ';


try {
  const profileNode = $('Get User Profile1').first().json;
  displayName = profileNode.displayName || prepareNode.reporter || 'ไม่ระบุ';
} catch(e) {
  displayName = prepareNode.reporter || 'ไม่ระบุ';
}
// ดึงชื่อกลุ่มจาก Get Group Summary node
let groupName = 'ไม่ระบุกลุ่ม';
try {
  const groupNode = $('Get Group Summary1').first().json;
  groupName = groupNode.groupName || prepareNode.group_id || 'ไม่ระบุกลุ่ม';
} catch(e) {
  groupName = prepareNode.group_id || 'ไม่ระบุกลุ่ม';
}

const ticketKey  = jiraNode.key || 'TICKET-????';
const caseType   = defaultNode.case_type || 'UNKNOWN';
const summary    = defaultNode.summary || prepareNode.summary || '-';
const isComplete = defaultNode.is_complete;
const missingArr = Array.isArray(defaultNode.missing_fields) ? defaultNode.missing_fields : [];
const extracted  = defaultNode.extracted_fields || {};

const jiraBaseUrl = 'https://uat-itsd.ksp.kln.com/browse';
const ticketUrl   = ticketKey !== 'TICKET-????' ? `${jiraBaseUrl}/${ticketKey}` : '-';

const typeLabel = {
  SUGAR:    'น้ำตาล 🍬',
  WS:       'ห้องชั่ง ⚖️',
  WH:       'โกดังเหล็ก 🏭',
  COIL:     'Steel Coil 🔩',
  WOODCHIP: 'ไม้สับ 🪵',
  TAPIOCA:  'มันสำปะหลัง 🌿',
  FREEZONE: 'Free Zone 🚢',
  GC:       'General Cargo 📦',
  PASSWORD: 'Password 🔑',
  KIOSK:    'Kiosk 🖥️',
  USER_IT:  'IT Support 💻',
  BARCODE:  'Barcode 📷',
  UNKNOWN:  'ทั่วไป 📋',
};

const now = new Date().toLocaleString('th-TH', {
  timeZone: 'Asia/Bangkok',
  hour:     '2-digit',
  minute:   '2-digit',
  day:      '2-digit',
  month:    '2-digit',
  year:     '2-digit'
});

const label      = typeLabel[caseType] || caseType;
const statusIcon = isComplete ? '✅ ข้อมูลครบ' : '⚠️ ข้อมูลยังไม่ครบ';

const extractedLines = Object.entries(extracted)
  .filter(([k, v]) => v)
  .map(([k, v]) => '  • ' + k + ': ' + v);

const lines = [
  '🔔 มีเคสใหม่เข้ามา!',
  '━━━━━━━━━━━━━━━━━━',
  '🎫 Ticket   : ' + ticketKey,
  '🔗 URL      : ' + ticketUrl,
  '📋 ประเภท   : ' + label,
  '📝 รายละเอียด: ' + summary,
  '👤 ผู้แจ้ง   : ' + displayName,
  '👥 กลุ่ม     : ' + groupName,
  '📊 สถานะ   : ' + statusIcon,
];

if (extractedLines.length > 0) {
  lines.push('');
  lines.push('📌 ข้อมูลที่ได้รับ:');
  extractedLines.forEach(l => lines.push(l));
}

if (!isComplete && missingArr.length > 0) {
  lines.push('');
  lines.push('❗ ข้อมูลที่ขาด: ' + missingArr.join(', '));
}

lines.push('');
lines.push('⏰ ' + now);
lines.push('━━━━━━━━━━━━━━━━━━');

const IT_GROUP_ID = 'C3d805526a7466a5385d5aa7b6e3fa32a';

return [{
  json: {
    to: IT_GROUP_ID,
    messages: [
      {
        type: 'text',
        text: lines.join('\n')
      }
    ]
  }
}];

