// ============================================
// Set Default Fields - รองรับทุก case_type
// ============================================

const aiOutput = $json.output ?? {};
const prepareData = $('Prepare Data').first().json;
const caseType = aiOutput.case_type || prepareData.detected_type || "UNKNOWN";
const extracted = aiOutput.extracted_fields || {};

// ============================================
// Map case_type → Jira fields
// ============================================
const categoryMap = {
  SUGAR:     "General Support",
  WS:        "KWMS",
  WH:        "KWMS",
  COIL:      "KWMS",
  WOODCHIP:  "KPWMS",
  TAPIOCA:   "KPWMS",
  FREEZONE:  "General Support",
  GC:        "KWMS GC",
  PASSWORD:  "General Support",
  KIOSK:     "General Support",
  USER_IT:   "General Support",
  BARCODE:   "KWMS",
  UNKNOWN:   "General Support",
};

const priorityMap = {
  SUGAR:    "1 Critical",
  WS:       "1 Critical",
  WH:       "1 Critical",
  COIL:     "1 Critical",
  WOODCHIP: "1 Critical",
  TAPIOCA:  "2 Important",
  FREEZONE: "3 Standard",
  GC:       "1 Critical",
  PASSWORD: "3 Standard",
  KIOSK:    "2 Important",
  USER_IT:  "3 Standard",
  BARCODE:  "1 Critical",
  UNKNOWN:  "3 Standard",
};

// ============================================
// Build dynamic summary
// ============================================
function buildSummary(type, fields, rawMessage) {
  const prefixes = {
    SUGAR:    "[KSP] Sugar",
    WS:       "[KSSP] WS",
    WH:       "[KSSP] WH",
    COIL:     "[KSP] COIL",
    WOODCHIP: "[KSP] WC",
    TAPIOCA:  "[KSP] Tapioca",
    FREEZONE: "[KSP] Free Zone",
    GC:       "[KSP] GC",
    PASSWORD: "[KSP] Reset Password",
    KIOSK:    "[KSSP] Kiosk",
    USER_IT:  "[KSP] User",
    BARCODE:  "[KSP] Barcode",
  };
  const prefix = prefixes[type] || "[KSP]";
  return `${prefix} : ${rawMessage.substring(0, 80)}`;
}

return [{
  json: {
    // Fixed Jira Fields
    project:    "IT Service Desk Thailand (Ticket)",
    issue_type: "Incident",
    mode:       { value: "Web Form" },
    urgency: { value:"3 Standard" },
    impact:  { value: "3 Effects one of few user" },
    technician: { value: "KSSP- App Support" },
    assignee:   null,
    site:       { value: "KSSP-Sriracha" },

    // Dynamic fields
    category:  { value : categoryMap[caseType] || categoryMap.UNKNOWN } ,
    priority:   priorityMap[caseType] || priorityMap.UNKNOWN,

    // จาก Prepare Data
    reporter:     prepareData.reporter,
    summary:      buildSummary(caseType, extracted, prepareData.raw_message),
    description:  prepareData.raw_message,
    received_at:  prepareData.received_at,
    replyToken:   prepareData.replyToken,

    // จาก AI (structured)
    case_type:        caseType,
    is_case:          aiOutput.is_case,
    is_complete:      aiOutput.is_complete,
    missing_fields:   aiOutput.missing_fields || [],
    action:           aiOutput.action || "",
    extracted_fields: extracted,

    // Backward-compatible fields (Sugar)
    product_code: extracted.product_code || null,
    warehouse:    extracted.warehouse    || null,
    quantity:     extracted.quantity     || null,
    unit:         extracted.unit         || null,

    // Barcode/WH fields
    truck_id:     extracted.truck_id     || null,
    barcode:      extracted.barcode      || null,

    // Password fields
    username:     extracted.username     || null,
    system:       extracted.system       || null,
  }
}];

// ============================================
// REGEX FILTER - รองรับทุกประเภทเคส
// Version 2.0
// ============================================

const body = $json.body || {};
const event = body.events?.[0] || {};
const messageText = (event.message?.text || "").normalize("NFC").replace(/\u00a0/g,"").trim();
const userId = event.source?.userId || "unknown";
const displayName = event.source?.displayName || event.message?.senderProfile?.displayName || userId;
const groupId = event.source?.groupId || null;
const sourceId = event.source?.groupId || event.source?.roomId || userId;
const sourceType = event.source?.type || "user";
const receivedAt = new Date().toISOString();

// ============================================
// PHASE 0: Event Type Filter
// ============================================
if (event.type !== "message" || event.message?.type !== "text") {
  return [{ json: { skip: true, skip_reason: "Not a text message", replyToken: event.replyToken } }];
}

// ============================================
// PHASE 1: ตรวจสอบ #แจ้งเคส (REQUIRED)
// ============================================
const casePrefix = "#แจ้งเคส";
const hasCasePrefix = messageText.trim().startsWith(casePrefix);

if (!hasCasePrefix) {
  return [{ json: { skip: true, skip_reason: "ไม่มี #แจ้งเคส prefix", raw_message: messageText, replyToken: event.replyToken } }];
}



const cleanMessage = messageText
  .replace(casePrefix, "")
  .normalize("NFC")
  .trim()
  .replace(/\s+/g, " ");
if (!cleanMessage || cleanMessage.length === 0) {
  return [{
    json: {
      skip: true,
      skip_reason: "ไม่มีรายละเอียดเคส",
      raw_message: messageText,
      replyToken: event.replyToken,
      reply_message: `กรุณาแจ้งในรูปแบบ:
#แจ้งเคส [ประเภท] [รายละเอียด]

📌 ตัวอย่างเคสที่ถูกต้อง:

🍬 น้ำตาล:
#แจ้งเคส เพิ่มยอด S43-2 วรรณา2 6000 กส

⚖️ ห้องชั่ง:
#แจ้งเคส WS ตีกลับ ใบชั่ง 3524739

🏭 โกดังเหล็ก:
#แจ้งเคส WH เอารถออกจาก 23A TRUCK_ID: 2972219

🔑 Password:
#แจ้งเคส Reset Password AD: PPhunpipat

🖥️ Kiosk:
#แจ้งเคส Kiosk ICD1_GATE_2I ใช้งานไม่ได้`
    }
  }];
}

// ดึง AD User (รองรับทั้ง @PPhunpipat และ PPhunpipat)
const adUserMatch = cleanMessage.match(/^@?([A-Za-z][A-Za-z0-9]{2,19})(?:\s|$)/);
const adUser = adUserMatch ? adUserMatch[1] : null;
const messageWithoutUser = adUser
  ? cleanMessage.replace(/^@?[A-Za-z][A-Za-z0-9]{2,19}\s*/, "").trim()
  : cleanMessage;

// ============================================
// PHASE 2: Quick Reject
// ============================================
const quickRejectPatterns = [
  { regex: /^.{1,3}$/, reason: "ข้อความสั้นเกินไป" },
  { regex: /^(สวัสดี|hi|hello|ok|โอเค|ครับ|ค่ะ)$/i, reason: "ข้อความทั่วไป" },
  { regex: /^[!@#$%^&*()]+$/, reason: "สัญลักษณ์เดียว" },
  { regex: /^[\u{1F300}-\u{1F9FF}]+$/u, reason: "Emoji เดียว" },
];

for (const p of quickRejectPatterns) {
  if (p.regex.test(messageWithoutUser)) {
    return [{
      json: {
        skip: true,
        skip_reason: `Quick Reject: ${p.reason}`,
        clean_message: cleanMessage,
        raw_message: messageText,
        replyToken: event.replyToken,
        reply_message: `กรุณาแจ้งในรูปแบบ:
#แจ้งเคส [ประเภท] [รายละเอียด]

📌 ตัวอย่างเคสที่ถูกต้อง:

