}

// ============================================
// PHASE 3: DETECT CASE TYPE + SCORING
// ============================================
let score = 0;
let reasons = [];
let detectedType = "UNKNOWN";

// --- กลุ่ม 1: Sugar (น้ำตาล) ---
const sugarPatterns = [
  { regex: /เพิ่ม(ยอด|น้ำตาล)/i,           points: 3, label: "เพิ่มยอดน้ำตาล" },
  { regex: /เติมน้ำตาล/i,                    points: 3, label: "เติมน้ำตาล" },
