  { regex: /ยกเลิก/i,                        points: 1, label: "ยกเลิก" },
];

// --- คำนวณคะแนนแต่ละกลุ่ม ---
const groups = [
  { name: "SUGAR",     patterns: sugarPatterns },
  { name: "BARCODE",   patterns: barcodePatterns },
  { name: "WH",        patterns: whPatterns },
  { name: "COIL",      patterns: coilPatterns },
  { name: "WS",        patterns: wsPatterns },
  { name: "WOODCHIP",  patterns: woodchipPatterns },
  { name: "TAPIOCA",   patterns: tapiocaPatterns },
  { name: "FREEZONE",  patterns: freezonePatterns },
  { name: "GC",        patterns: gcPatterns },
  { name: "PASSWORD",  patterns: passwordPatterns },
  { name: "KIOSK",     patterns: kioskPatterns },
  { name: "USER_IT",   patterns: userPatterns },
];

let groupScores = {};
for (const group of groups) {
  let gs = 0;
  for (const p of group.patterns) {
    if (p.regex.test(cleanMessage)) {
      gs += p.points;
      score += p.points;
      reasons.push(`[${group.name}] +${p.points}: ${p.label}`);
    }
  }
  groupScores[group.name] = gs;
}

// แก้ไขทั่วไป
for (const p of editPatterns) {
  if (p.regex.test(cleanMessage)) {
    score += p.points;
    reasons.push(`[EDIT] +${p.points}: ${p.label}`);
  }
}

if (messageWithoutUser.length < 10) {
  score -= 1;
  reasons.push("-1: ข้อความสั้น");
}

// หา case type ที่ได้คะแนนสูงสุด
const topGroup = Object.entries(groupScores).sort((a, b) => b[1] - a[1])[0];
if (topGroup && topGroup[1] >= 2) {
  detectedType = topGroup[0];
}





// ============================================
// PHASE 4: DECISION
// ============================================
let needAI = false;
let decision = "";

if (score >= 5) {
  needAI = false;
  decision = "HIGH_SCORE_ACCEPT";
} else if (score >= 2) {
  needAI = true;
  decision = "MEDIUM_SCORE_NEED_AI";
} else {
  needAI = true;
  decision = "LOW_SCORE_BUT_HAS_PREFIX";
}


// ============================================
// OUTPUT
// ============================================
return [{
  json: {
    skip: false,
    need_ai: needAI,
    is_case_report: true,

    // Scoring
    score: score,
    reasons: reasons.join(", "),
    decision: decision,
    detected_type: detectedType,
    group_scores: groupScores,

    // Data
    reporter: userId,
    display_name: displayName,
    group_id: groupId,
    ad_user: adUser || "",
    summary: messageWithoutUser,
    source_id: sourceId,
    source_type: sourceType,
    raw_message: messageWithoutUser,
    original_message: messageText,
    received_at: receivedAt,
    replyToken: event.replyToken
  }
}];

// ============================================
