// ============================================

const jiraNode    = $('Create an issue').first().json;
const defaultNode = $('Set default filed').first().json;
const prepareNode = $('Prepare Data').first().json;

const ticketKey  = jiraNode.key || "TICKET-????";
const caseType   = defaultNode.case_type || "UNKNOWN";
const isComplete = defaultNode.is_complete;
const missingArr = Array.isArray(defaultNode.missing_fields) ? defaultNode.missing_fields : [];
const replyToken = defaultNode.replyToken || prepareNode.replyToken || "";

const typeLabel = {
  SUGAR:    "น้ำตาล 🍬",
  WS:       "ห้องชั่ง ⚖️",
  WH:       "โกดังเหล็ก 🏭",
  COIL:     "Steel Coil 🔩",
  WOODCHIP: "ไม้สับ 🪵",
  TAPIOCA:  "มันสำปะหลัง 🌿",
  FREEZONE: "Free Zone 🚢",
  GC:       "General Cargo 📦",
  PASSWORD: "Password 🔑",
  KIOSK:    "Kiosk 🖥️",
  USER_IT:  "IT Support 💻",
  BARCODE:  "Barcode 📷",
  UNKNOWN:  "ทั่วไป 📋",
};

const fieldHint = {
  product_code:  "รหัสสินค้า เช่น S43-2 / B-001",
  warehouse:     "ชื่อคลัง เช่น วรรณา2 / WH01 / Silo A",
  quantity:      "จำนวน เช่น 6000 กส / 20 ตู้",
  unit:          "หน่วย เช่น กส / ตู้ / กก",
  truck_id:      "TRUCK_ID เช่น 2972219",
  barcode:       "Barcode เช่น SP202217725470T",
  username:      "ชื่อ User (AD) เช่น NHongsuwan",
  system:        "ระบบ เช่น AD / O365 / KWMS / VPN",
  scale_no:      "เลขใบชั่ง เช่น 3507166",
  lot:           "LOT เช่น 1125C06",
  gate_location: "จุด/Gate เช่น ICD1 Gate 2",
  symptom:       "อาการ เช่น โปรแกรมค้าง / เข้าใช้งานไม่ได้",
  coil_id:       "Coil ID เช่น 5684422",
  location:      "ตำแหน่ง เช่น CY6 / 23C",
  date:          "วันที่ เช่น 02/09/2568",
  vessel:        "ชื่อเรือ",
};

const now = new Date().toLocaleString("th-TH", {
  timeZone: "Asia/Bangkok",
  hour:     "2-digit",
  minute:   "2-digit",
  day:      "2-digit",
  month:    "2-digit",
  year:     "2-digit"
});

const label = typeLabel[caseType] || caseType;

let textLines;

if (isComplete || missingArr.length === 0) {
  textLines = [
    "✅ รับเคสเรียบร้อยครับ",
    "",
    "🎫 Ticket: " + ticketKey,
    "📋 ประเภท: " + label,
    "⏰ " + now,
    "",
    "ทีม IT จะดำเนินการและแจ้งผลกลับครับ 🙏"
  ];
} else {
  const missingLines = missingArr.map(function(f) {
    return "  - " + (fieldHint[f] || f);
  });
  textLines = [
    "✅ รับเคสแล้วครับ",
    "",
    "🎫 Ticket: " + ticketKey,
    "📋 ประเภท: " + label,
    "⏰ " + now,
    "",
    "⚠️ ข้อมูลยังไม่ครบ กรุณาแจ้งเพิ่มครับ:"
  ].concat(missingLines);
}

// สร้าง LINE API body object ครบเลย
// HTTP Request node ใช้แค่ {{ $json }} ตัวเดียว
return [{
  json: {
    replyToken: replyToken,
    messages: [
      {
        type: "text",
        text: textLines.join("\\n")
      }
    ]
  }
}];

